  'c10_tam_u2_c2': {"id": "quiz_c10_tam_u2_c2", "chapterId": "c10_tam_u2_c2", "titleEn": "Prose: Ketkiradha En Kural! (Voice of Wind): Board Practice Quiz", "titleTa": "உரைநடை: கேட்கிறதா என் குரல்! (காற்றின் தன்வரலாறு): அரசு தேர்வு மாதிரி வினாடி வினா", "totalMarks": 10, "timeLimitMinutes": 5, "questions": [{"id": "q1", "type": "mcq", "difficulty": "medium", "questionTa": "உலகக் காற்று நாளாகக் கொண்டாடப்படும் நாள் எது?", "questionEn": "Which day is observed as World Wind Day?", "optionsTa": ["ஜூன் 5", "ஜூன் 15", "சூலை 15", "ஆகத்து 15"], "optionsEn": ["June 5", "June 15", "July 15", "August 15"], "correctAnswerIndex": 1, "explanationTa": "சரியான விடை: ஜூன் 15.", "explanationEn": "Correct answer is June 15."}, {"id": "q2", "type": "mcq", "difficulty": "easy", "questionTa": "உரைநடை: கேட்கிறதா என் குரல்! (காற்றின் தன்வரலாறு) தமிழ்நாடு அரசின் எந்தப் பாடத்திட்டத்தில் இடம்பெற்றுள்ளது?", "questionEn": "Under which state curriculum is Prose: Ketkiradha En Kural! (Voice of Wind) designated?", "optionsTa": ["சமச்சீர் கல்வி பத்தாம் வகுப்பு", "சிபிஎஸ்இ", "ஐசிஎஸ்இ", "பழைய மெட்ரிக் முறை"], "optionsEn": ["Samacheer Kalvi Class 10", "CBSE", "ICSE", "Old Matric"], "correctAnswerIndex": 0, "explanationTa": "இது தமிழ்நாடு அரசுப் பாடநூல் கழகத்தின் பத்தாம் வகுப்பு சமச்சீர் பாடத்திட்டம்.", "explanationEn": "Prescribed as part of TN State Board Samacheer Kalvi Class 10 syllabus."}]},
