  'c10_tam_u2_c1': {"id": "vid_c10_tam_u2_c1", "chapterId": "c10_tam_u2_c1", "titleEn": "Poetry: Kaatre Vaa! (Mahakavi Bharati) Animated Storyboard", "titleTa": "கவிதை: காற்றே வா! (மகாகவி பாரதியார்) அனிமேஷன் பாடம்", "durationSeconds": 120, "scenes": [{"sceneNumber": 1, "titleEn": "Introduction & Context", "titleTa": "பாட அறிமுகமும் வரலாற்றுப் பின்னணியும்", "visualDescription": "Opening visualization introducing Poetry: Kaatre Vaa! (Mahakavi Bharati) with authentic Tamil Nadu cultural motifs.", "narrationEn": "Welcome to the visual study module for Poetry: Kaatre Vaa! (Mahakavi Bharati). Today we discover its literary and cultural essence.", "narrationTa": "கவிதை: காற்றே வா! (மகாகவி பாரதியார்) பாடத்தின் காட்சி விளக்கத்திற்கு உங்களை வரவேற்கிறோம். இப்பாடத்தின் மூலக்கருத்தை இப்போது காண்போம்.", "conceptKey": "பாட அறிமுகம்"}, {"sceneNumber": 2, "titleEn": "Core Concept Deep Dive", "titleTa": "பாடத்தின் முதன்மைக் கருத்து", "visualDescription": "Illustrated step-by-step exposition of Poetry: Kaatre Vaa! (Mahakavi Bharati) highlighting primary verses and passages.", "narrationEn": "Bharati appeals to the wind to bestow Prana Rasam (vital oxygen).", "narrationTa": "பாரதியார் காற்றைப் பிராண ரசத்தை (உயிர்வளி) அள்ளித் தரும்படி வேண்டுகிறார்.", "conceptKey": "மையக்கருத்து"}, {"sceneNumber": 3, "titleEn": "Board Exam Takeaways", "titleTa": "தேர்வு வழிகாட்டுதல்", "visualDescription": "Flashcards presenting high-frequency keywords, literary grammar notations, and model questions.", "narrationEn": "Remember these vital keywords and author citations for maximum scores in your Tamil board examination.", "narrationTa": "அரசு பொதுத்தேர்வில் அதிக மதிப்பெண்கள் பெற இப்பாடத்தின் முக்கிய வரிகளையும் ஆசிரியர் குறிப்புகளையும் நினைவில் கொள்க.", "conceptKey": "தேர்வு வெற்றி"}]},
  'c10_tam_u2_c2': {"id": "vid_c10_tam_u2_c2", "chapterId": "c10_tam_u2_c2", "titleEn": "Prose: Ketkiradha En Kural! (Voice of Wind) Animated Storyboard", "titleTa": "உரைநடை: கேட்கிறதா என் குரல்! (காற்றின் தன்வரலாறு) அனிமேஷன் பாடம்", "durationSeconds": 120, "scenes": [{"sceneNumber": 1, "titleEn": "Introduction & Context", "titleTa": "பாட அறிமுகமும் வரலாற்றுப் பின்னணியும்", "visualDescription": "Opening visualization introducing Prose: Ketkiradha En Kural! (Voice of Wind) with authentic Tamil Nadu cultural motifs.", "narrationEn": "Welcome to the visual study module for Prose: Ketkiradha En Kural! (Voice of Wind). Today we discover its literary and cultural essence.", "narrationTa": "உரைநடை: கேட்கிறதா என் குரல்! (காற்றின் தன்வரலாறு) பாடத்தின் காட்சி விளக்கத்திற்கு உங்களை வரவேற்கிறோம். இப்பாடத்தின் மூலக்கருத்தை இப்போது காண்போம்.", "conceptKey": "பாட அறிமுகம்"}, {"sceneNumber": 2, "titleEn": "Core Concept Deep Dive", "titleTa": "பாடத்தின் முதன்மைக் கருத்து", "visualDescription": "Illustrated step-by-step exposition of Prose: Ketkiradha En Kural! (Voice of Wind) highlighting primary verses and passages.", "narrationEn": "Four winds: East (Kondal), West (Kodai), North (Vaadai), South (Thendral).", "narrationTa": "கிழக்கிலிருந்து வீசும் காற்று கொண்டல், மேற்கிலிருந்து கோடை, வடக்கிலிருந்து வாடை, தெற்கிலிருந்து தென்றல்.", "conceptKey": "மையக்கருத்து"}, {"sceneNumber": 3, "titleEn": "Board Exam Takeaways", "titleTa": "தேர்வு வழிகாட்டுதல்", "visualDescription": "Flashcards presenting high-frequency keywords, literary grammar notations, and model questions.", "narrationEn": "Remember these vital keywords and author citations for maximum scores in your Tamil board examination.", "narrationTa": "அரசு பொதுத்தேர்வில் அதிக மதிப்பெண்கள் பெற இப்பாடத்தின் முக்கிய வரிகளையும் ஆசிரியர் குறிப்புகளையும் நினைவில் கொள்க.", "conceptKey": "தேர்வு வெற்றி"}]},
